import{CHARACTERS,PRESETS}from'./characters.js';import{ARENA,createPrototypeState,getActionHint,getComboRank,getFormation,getResults,getWeakPoint,stepPrototype,tapPrototype}from'./physics.js?v=v33-impact-1';
const KEY='qunxiong-world-blackwind-prototype-v3-3',canvas=document.querySelector('canvas'),ctx=canvas.getContext('2d'),setup=document.querySelector('[data-setup]'),battle=document.querySelector('[data-battle]'),roster=document.querySelector('[data-roster]'),teamBox=document.querySelector('[data-team]'),presets=document.querySelector('[data-presets]'),result=document.querySelector('.result');canvas.width=ARENA.width;canvas.height=ARENA.height;let chosen=[...PRESETS.burst.team],state=null,last=0,raf=0,frames=0,fpsIn=0,hudIn=0,audio=null,eventSeen=0;
