function setupUI(){presets.innerHTML=Object.entries(PRESETS).map(([id,p])=>`<button data-preset="${id}">${p.name}</button>`).join('');roster.innerHTML=Object.entries(CHARACTERS).map(([id,c])=>`<button class="card" data-character="${id}"><b style="color:${c.color}">${c.name}</b><span>${c.role}・${c.passive}</span><small>${c.skill}</small></button>`).join('');drawChoice();}
