function hero(f,i,alpha=1){const c=CHARACTERS[f.id];ctx.save();ctx.globalAlpha=alpha;ctx.translate(f.x,f.y);ctx.fillStyle='#02081299';ctx.beginPath();ctx.ellipse(0,20,20,7,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#182536';ctx.strokeStyle=c.color;ctx.lineWidth=4;ctx.beginPath();ctx.ellipse(0,2,18,23,0,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#ecc39c';ctx.beginPath();ctx.arc(0,-9,10,0,Math.PI*2);ctx.fill();ctx.fillStyle=c.color;ctx.beginPath();ctx.moveTo(-13,-8);ctx.lineTo(0,-28);ctx.lineTo(14,-8);ctx.lineTo(6,-15);ctx.closePath();ctx.fill();ctx.restore();}
