function boss(){const b=state.boss,wp=getWeakPoint(state);ctx.save();ctx.translate(b.x+b.recoilX,b.y);if(b.flash)ctx.filter='brightness(2.5)';ctx.fillStyle='#252b3a';ctx.strokeStyle='#d7b65b';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-42,38);ctx.lineTo(-34,-16);ctx.lineTo(-18,-48);ctx.lineTo(0,-58);ctx.lineTo(24,-43);ctx.lineTo(43,38);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#ddb58e';ctx.beginPath();ctx.arc(0,-18,17,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#ee574e';ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(20,-8);ctx.lineTo(55,30);ctx.stroke();ctx.restore();ctx.strokeStyle='#fff36b';ctx.lineWidth=3;ctx.beginPath();ctx.arc(wp.x,wp.y,12,0,Math.PI*2);ctx.stroke();if(state.shield){ctx.strokeStyle='#f2de8b';ctx.lineWidth=5;ctx.beginPath();ctx.arc(state.core.x,state.core.y,38,0,Math.PI*2);ctx.stroke();}}
function skillVfx(){const k=state.skill;if(!k)return;const c=CHARACTERS[k.id],p=k.elapsed/k.duration;ctx.save();ctx.globalCompositeOperation='lighter';ctx.strokeStyle=c.color;ctx.fillStyle=c.color;ctx.shadowColor=c.color;ctx.shadowBlur=16;if(k.motion==='slash'){ctx.lineWidth=12;ctx.beginPath();ctx.arc(state.boss.x,state.boss.y,70,-2.8+p*2,.5+p*2);ctx.stroke();}else if(k.motion==='smash'){ctx.lineWidth=9;for(let i=0;i<3;i++){ctx.beginPath();ctx.arc(state.boss.x,state.boss.y,25+p*65+i*10,0,Math.PI*2);ctx.stroke();}}else if(k.motion==='support'){ctx.globalAlpha=.45;ctx.beginPath();ctx.arc(180,300,35+p*130,0,Math.PI*2);ctx.fill();}else if(k.motion==='ricochet'){ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(k.x,k.y);ctx.lineTo(k.x<180?330:30,k.y-45);ctx.stroke();}else if(k.motion==='burn'){ctx.lineWidth=15;ctx.beginPath();ctx.moveTo(k.x-55,k.y+30);ctx.lineTo(k.x,k.y);ctx.stroke();for(let i=0;i<5;i++){ctx.beginPath();ctx.arc(k.x-15+i*8,k.y+20,4+i,0,Math.PI*2);ctx.fill();}}else if(k.motion==='pierce'){ctx.lineWidth=6;ctx.setLineDash([16,8]);ctx.beginPath();ctx.moveTo(20,k.y);ctx.lineTo(340,k.y);ctx.stroke();}else if(k.motion==='storm'){ctx.lineWidth=6;for(let i=0;i<4;i++){ctx.beginPath();ctx.moveTo(120+i*40,10);ctx.lineTo(150+i*15,state.boss.y);ctx.lineTo(130+i*30,state.boss.y+50);ctx.stroke();}}else if(k.motion==='guard'){ctx.lineWidth=9;ctx.beginPath();ctx.arc(180,300,70,Math.PI,Math.PI*2);ctx.stroke();}else if(k.motion==='hunt'){ctx.lineWidth=8;for(let i=0;i<4;i++){ctx.beginPath();ctx.moveTo(state.boss.x-70+i*25,state.boss.y+60);ctx.lineTo(state.boss.x-25+i*25,state.boss.y-60);ctx.stroke();}}else{ctx.lineWidth=10;ctx.beginPath();ctx.moveTo(k.x-65,k.y);ctx.lineTo(k.x,k.y);ctx.stroke();}ctx.restore();hero({x:k.x,y:k.y,id:k.id},0);}
function events(){for(const e of state.events){const a=Math.max(0,Math.min(1,e.life/.7)),big=['break','skill-intro','counter','climax','power'].includes(e.type);ctx.save();ctx.globalAlpha=a;ctx.textAlign='center';ctx.fillStyle=e.color||'#fff';ctx.strokeStyle='#081018';ctx.lineWidth=big?7:5;ctx.font=`900 ${big?24:e.type.includes('hit')?20:17}px sans-serif`;const rise=(1-a)*22;ctx.strokeText(e.text||'',e.x,e.y-rise);ctx.fillText(e.text||'',e.x,e.y-rise);ctx.restore();}}
