function sync(){if(!state)return;ui.time.textContent=state.timeLeft.toFixed(1);ui.combo.textContent=`${state.combo} HIT`;ui.rank.textContent=getComboRank(state.combo);ui.power.style.width=`${state.power}%`;ui.powerLabel.textContent=state.powerTier?`${CHARACTERS[state.team[0]].synergy}・${state.powerTier===4?'MAX':'ⅠⅡⅢ'[state.powerTier-1]}`:'蓄力中';ui.break.style.width=`${state.breakGauge}%`;ui.breakLabel.textContent=state.breakIn?`BREAK ${state.breakIn.toFixed(1)}s`:`弱點：${['左','上','右'][state.boss.weakSide]}`;ui.hint.textContent=getActionHint(state);ui.banner.textContent=state.skill?(state.skill.ultimate?CHARACTERS[state.skill.id].ultimate:CHARACTERS[state.skill.id].skill):state.climaxIn?'天下無雙・全隊追擊':state.boss.move?.name||'';if(state.complete&&!result.classList.contains('show')){const r=getResults(state);result.innerHTML=`<h2>V3.3 戰鬥分析</h2><p>${r.team.map(id=>CHARACTERS[id].name).join('・')}</p><dl><dt>最高 Combo</dt><dd>${r.highestCombo}</dd><dt>總傷害</dt><dd>${r.damage}</dd><dt>平均有效 Hit 間隔</dt><dd>${r.averageHitGap}s</dd><dt>Perfect Flip</dt><dd>${r.perfectFlips}</dd><dt>Counter</dt><dd>${r.counters}</dd><dt>Perfect Counter</dt><dd>${r.perfectCounters}</dd><dt>Power I／II</dt><dd>${r.powerLevels[0]}／${r.powerLevels[1]}</dd><dt>Power III／MAX</dt><dd>${r.powerLevels[2]}／${r.powerLevels[3]}</dd><dt>Assist Dash</dt><dd>${r.assistDashes}</dd><dt>BREAK</dt><dd>${r.breaks}</dd><dt>技能／Ultimate</dt><dd>${r.skills}／${r.ultimates}</dd><dt>剩餘 HP</dt><dd>${r.hp}</dd></dl><button type="button">同隊再戰</button>`;result.classList.add('show');result.querySelector('button').onclick=start;try{localStorage.setItem(KEY,JSON.stringify({last:r,team:chosen}));}catch{}}}
function sound(type){try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.type=type.includes('counter')?'square':'triangle';o.frequency.value=type.includes('power')?520:type.includes('dash')?360:220;g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.08);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+.08);}catch{}}
function frame(now){const dt=last?Math.min(.034,(now-last)/1000):.016;last=now;if(state){stepPrototype(state,dt);if(state.events.length>eventSeen){const e=state.events[state.events.length-1];sound(e.type);eventSeen=state.events.length;}}render();hudIn-=dt;if(hudIn<=0){sync();hudIn=.08;}frames++;fpsIn+=dt;if(fpsIn>=1){document.body.dataset.fps=String(Math.round(frames/fpsIn));frames=0;fpsIn=0;}raf=requestAnimationFrame(frame);}canvas.addEventListener(window.PointerEvent?'pointerdown':'touchstart',e=>{e.preventDefault();if(state){const a=tapPrototype(state);sound(a.type);}},{passive:false});document.querySelector('[data-start]').onclick=start;document.querySelector('[data-back]').onclick=back;setupUI();requestAnimationFrame(frame);
